{
  "export": "siem.alerts.get",
  "record": {
    "alert_id": "AL-77522",
    "identity": "Identity/ID-40732",
    "kind": "credential_compromise",
    "opened_at": "2026-06-05T23:41:00",
    "rule": {
      "name": "Cloud access key used from an unregistered egress",
      "rule_id": "RUL-KEYEGRESS-2",
      "status": "enabled",
      "version": "v2"
    },
    "severity": "high",
    "status": "open",
    "summary": "billing gateway access key used from an unregistered cloud-hosting egress while the registered gateway host was idle"
  }
}

{
  "channel": "#soc-incidents",
  "messages": [
    {
      "author": "Rohan Pradhan",
      "text": "svc-billing-gw stays on the metered basis \u2014 the 06-04 snapshot is 4 keys, not the 2-key onboarding figure.",
      "ts": "2026-06-05T11:02:00"
    },
    {
      "author": "Imre Haviland",
      "text": "svc-billing-recon's review is the 23rd, so it is not part of next week's count. The old ledger booking was cancelled and rebooked; count it once.",
      "ts": "2026-06-08T09:25:00"
    },
    {
      "author": "Nienke Achterberg",
      "text": "No expedited rollover on this one unless it comes to me; a rollover of every billing principal needs my sign-off.",
      "ts": "2026-06-08T09:40:00"
    }
  ],
  "thread_id": "CHAT-1002",
  "title": "SEC-0002 billing custody reviews week of 06-15"
}

{
  "case_reference": "SEC-0002",
  "messages": [
    {
      "author": "operations",
      "sent_at": "2026-06-08T08:35:00",
      "text": "Use immutable subject KEY-CLOUD-ACCESS; the similarly named archived record is not in scope."
    },
    {
      "author": "governance",
      "sent_at": "2026-06-08T08:41:00",
      "text": "Current revision is v1. Confirm the signed approval before any state change."
    },
    {
      "author": "requester",
      "sent_at": "2026-06-08T08:47:00",
      "text": "Please leave the stakeholder communication as a draft for human review."
    }
  ],
  "thread_id": "OPS-SECOPS-0002"
}

